cat > outputs/app/app.js <<'"'EOF'
(() => {
const data=window.EVAL_FIXTURES.dashboard;
const query=new URLSearchParams(location.search);
const screen=['live','stale','surge'].includes(query.get('screen'))?query.get('screen'):'live';
const tv=document.documentElement.dataset.display==='tv';
const stale=screen==='stale';
const incidents=data.incidents.slice(0,screen==='surge'?data.surgeCount:data.openCount);
let page=0;
const pageSize=7;
const icon=(name)=>name==='sun'?'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2\"/></svg>':'<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"12\" rx=\"1\"/><path d=\"M8 21h8m-4-5v5\"/></svg>';
const escape=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
document.getElementById('app').innerHTML="'`
<a class="skip" href="#incidents">Skip to incidents</a>
<header class="topbar"><div class="wordmark"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M16 2 29 16 16 30 3 16Z" stroke="currentColor" stroke-width="1.5"/><path d="M11 23V9l10 14V9" stroke="currentColor" stroke-width="2"/></svg><span>northwind</span><span class="top-label">Operations / Incidents</span></div><div class="tools"><button id="display" aria-label="Switch to ${tv?'"'laptop':'TV'} view\">"'${icon('"'display')}<span>"'${tv?'"'TV view':'Laptop view'}</span></button><button id=\"theme\" aria-label=\"Switch color theme\">"'${icon('"'sun')}<span id=\"theme-label\"></span></button></div></header>
<main class=\""'${stale?'"'stale':''}\"><div class=\"heading\"><div><p class=\"eyebrow\">Operations room</p><h1>Incident overview</h1></div><div class=\"freshness\"><div class=\"fresh-label\"><span class=\"dot\"></span>"'${stale?'"'Updates paused':'Live snapshot'}</div><div class=\"muted\">"'${stale?'"'Last received':'Updated'} <span class=\"mono\">"'${stale?data.staleAsOf:data.displayTime}</span> · ${data.displayDate}</div></div></div>
${stale?`<div class="stale-banner" role="status"><strong>Data is out of date.</strong><span>Last received at ${data.staleAsOf}. Incident status, counts and durations may have changed.</span></div>`:'"''}
<section class=\"metrics\" aria-label=\"Incident metrics\"><div class=\"metric\"><h2 class=\"metric-label\">Open incidents</h2><div class=\"metric-value mono\">"'${incidents.length}</div><div class="metric-bottom"><strong>1 SEV1</strong><span>· 2 SEV2 · ${incidents.length-3} SEV3</span></div><div class="severity-strip" aria-hidden="true">${incidents.map(i=>`<i class="s${i.severity}"></i>`).join('"'')}</div></div><div class=\"metric\"><h2 class=\"metric-label\">Mean time to resolve · 7d</h2><div class=\"metric-value mono\">"'${data.mttr}</div><p class="metric-bottom">↓ ${data.mttrChange} vs last week</p></div><div class="metric"><h2 class="metric-label">Pages today</h2><div class="metric-value mono">${data.pages}</div><p class="metric-bottom">↑ ${data.pagesDelta} vs yesterday</p></div><div class="metric"><h2 class="metric-label">SLO budget left</h2><div class="metric-value mono">${data.slo}</div><p class="metric-bottom">↓ ${data.sloChange}</p></div></section>
<div class="workspace"><section class="incident-panel" id="incidents" tabindex="-1" aria-labelledby="incident-heading"><div class="section-head"><h2 id="incident-heading">Open incidents <span class="count" id="result-count"></span></h2><div class="filters"><label class="search"><span class="sr-only">Search incidents by title, ID or service</span><input id="search" type="search" placeholder="Search incidents" autocomplete="off"></label><label><span class="sr-only">Filter by severity</span><select id="severity"><option value="all">All severities</option><option value="1">SEV1</option><option value="2">SEV2</option><option value="3">SEV3</option></select></label></div></div>
<div class="table-wrap"><table aria-label="Open incidents"><thead><tr><th scope="col">Severity</th><th scope="col">Incident / service</th><th scope="col">Status</th><th scope="col">Commander</th><th scope="col">Duration</th></tr></thead><tbody id="rows"></tbody></table><p class="empty" id="empty" hidden>No incidents match your filters.</p></div><div id="pagination" class="pager"></div><p class="table-note">Mitigated and monitoring incidents remain open until resolved.${screen==='"'live'?' Open count ↑ 2 vs yesterday.':''}</p><span class=\"sr-only\" id=\"announce\" role=\"status\" aria-live=\"polite\"></span></section>
<aside aria-label=\"Operational context\"><section><div class=\"section-head\"><h2>On call now</h2><span class=\"until\">Until "'${data.until}</span></div><div class="oncall-row"><span class="label">Primary</span><p class="person">${data.primary}</p></div><div class="oncall-row"><span class="label">Secondary</span><p class="person">${data.secondary}</p></div><p class="commander-note">SEV1 incident commander is unassigned.</p></section><section><div class="section-head"><h2>Incidents by service</h2><span class="until">30 days</span></div>${data.services.map(s=>`<div class="service-row"><span>${s.name}</span><span class="mono">${s.value}</span><div class="track" aria-hidden="true"><div class="bar" style="width:${s.value/14*100}%"></div></div></div>`).join('"'')}</section><section><div class=\"section-head\"><h2>Recently resolved</h2><span class=\"count\">"'${data.resolved.length}</span></div>${data.resolved.map(i=>`<div class="resolved-item"><button class="incident-link" data-incident="${i.id}">${i.title}</button><p class="resolved-meta"><span class="mono">${i.id}</span> · SEV${i.severity} · Resolved<br>${i.service} · ${i.duration}</p></div>`).join('"'')}</section></aside></div></main>
<footer><span>Northwind Logistics <span aria-hidden=\"true\">/</span> Incident operations</span><span>"'${stale?'"'Last received '+data.staleAsOf:'Snapshot '+data.displayTime} · Durations as reported</span></footer>
<dialog id=\"detail\" aria-labelledby=\"detail-title\"><div class=\"dialog-top\"><span id=\"detail-id\" class=\"mono\"></span><button id=\"close-detail\" aria-label=\"Close incident details\">Close <span aria-hidden=\"true\">×</span></button></div><div id=\"detail-content\"></div></dialog>"'`;
const rows=document.getElementById('"'rows');
const search=document.getElementById('search'),severity=document.getElementById('severity');
function render(){
 const term=search.value.trim().toLowerCase();
 const filtered=incidents.filter(i=>(severity.value==='all'||String(i.severity)===severity.value)&&[i.id,i.title,i.service,i.commander||'unassigned'].join(' ').toLowerCase().includes(term));
 const pages=Math.max(1,Math.ceil(filtered.length/pageSize));page=Math.min(page,pages-1);
 const visible=tv?filtered.slice(page*pageSize,(page+1)*pageSize):filtered;
 rows.innerHTML=visible.map(i=>"'`<tr class="${i.severity===1?'"'priority':''}\"><td><span class=\"sev sev-"'${i.severity}">SEV${i.severity}</span></td><td><button class="incident-link" data-incident="${i.id}">${escape(i.title)}</button><div class="subline"><span class="mono">${i.id}</span><span>${i.service}</span></div></td><td class="state">${i.status}</td><td class="owner ${i.commander?'"'':'missing'}\">"'${i.commander||'"'Unassigned'}</td><td class=\"age mono\">"'${i.duration}</td></tr>`).join('"'');
 document.getElementById('empty').hidden=filtered.length>0;
 document.getElementById('result-count').textContent=filtered.length===incidents.length?incidents.length:"'`${filtered.length} of ${incidents.length}`;
 document.getElementById('"'pagination').innerHTML=tv&&filtered.length>pageSize?"'`<span>Showing ${page*pageSize+1}–${Math.min((page+1)*pageSize,filtered.length)} of ${filtered.length} · TV pages keep text readable</span><div class="pager-controls"><button id="prev" ${page===0?'"'disabled':''} aria-label=\"Previous incident page\">←</button><span>"'${page+1} / ${pages}</span><button id="next" ${page===pages-1?'"'disabled':''} aria-label=\"Next incident page\">→</button></div>"'`:`<span>${filtered.length?`Showing all ${filtered.length} open incidents`:'"''}</span>"'`;
 document.getElementById('"'announce').textContent="'`${filtered.length} matching incidents${tv?'"', page '+(page+1)+' of '+pages:''}"'`;
}
search.addEventListener('"'input',()=>{page=0;render()});severity.addEventListener('change',()=>{page=0;render()});
